import { newCatalog } from './new-icon-catalog.js';
import { approvedIcons } from './approved-icons.js';
import { catalog } from './icon-catalog.js';
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function optionsFor(n){const base=newCatalog[n.id]||catalog[n.id]||(approvedIcons[n.id]?[{key:'approved-'+approvedIcons[n.id].key,title:'נבחר',description:'האייקון שאושר',src:approvedIcons[n.id].src}]:[]);return n.packageIcon?[...base,{key:'package',title:'בחבילה',description:'האייקון בחבילת Revit העדכנית',src:n.packageIcon}]:base;}
export function choiceKey(n){const options=optionsFor(n);const exact=options.find(o=>o.src===n.icon);if(exact)return exact.key;return n.icon?.startsWith('data:')&&options.some(o=>o.key===n.iconChoice)?n.iconChoice:null;}
export function choicesHTML(n,staged=false){const options=optionsFor(n);if(!options.length)return '';return `<div class="icon-choices" role="group" aria-label="אייקונים עבור ${escape(n.label.replaceAll('\n',' '))}">${options.map(o=>`<button type="button" class="icon-option ${choiceKey(n)===o.key?'chosen':''}" data-icon-node="${escape(n.id)}" data-icon-key="${o.key}" ${staged?'data-stage-icon="true"':''} aria-pressed="${choiceKey(n)===o.key}" aria-label="${escape(o.title+' — '+o.description)}"><span class="choice-check" aria-hidden="true">${choiceKey(n)===o.key?'✓':''}</span><img src="${o.src}" alt=""><b>${o.title}</b><span>${escape(o.description)}</span></button>`).join('')}</div>`;}
export function galleryHTML(nodes,all){const items=nodes.filter(n=>optionsFor(n).length);return `<div class="icon-gallery-intro"><div><span class="eyebrow">ICON LIBRARY</span><h2>אותו כלי. סימן אחר.</h2><p>מקור, חלופה קווית וחלופה סמלית. לחיצה בוחרת ושומרת מיד.</p></div><span class="gallery-count">${items.length} כלים לבחירה</span></div><div class="icon-gallery">${items.map(n=>{const parent=all.find(x=>x.id===n.parent);return `<article class="icon-comparison"><div class="comparison-heading"><div><small>${escape(parent?.label||'רעיונות')}</small><h3 dir="auto">${escape(n.label.replaceAll('\n',' '))}</h3></div><button data-edit="${escape(n.id)}" aria-label="עריכת ${escape(n.label.replaceAll('\n',' '))}">פרטים</button></div>${choicesHTML(n)}<div class="actual-size"><span>תצוגה קטנה בסרגל</span>${optionsFor(n).map(o=>`<img src="${o.src}" width="20" height="20" alt="${o.title}">`).join('')}</div></article>`}).join('')}</div>${items.length?'':'<div class="empty">אין כלים שתואמים לסינון.</div>'}`;}
